$('enter').addEventListener('click',()=>{if(mode!=='intro')return;mode='approach';startTime=clock.elapsedTime;$('intro').style.opacity=0;$('intro').style.pointerEvents='none';});
function clearInput(){keys.clear();joy.x=joy.y=0;joy.id=null;lookId=null;$('knob').style.transform='';}let lookId=null,lastX=0,lastY=0;
const stick=$('stick');stick.addEventListener('pointerdown',e=>{if(joy.id!==null)return;e.preventDefault();joy.id=e.pointerId;stick.setPointerCapture(e.pointerId);updateJoy(e);});function updateJoy(e){const r=stick.getBoundingClientRect();let x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;const d=Math.hypot(x,y),limit=37;if(d>limit){x*=limit/d;y*=limit/d;}joy.x=x/limit;joy.y=y/limit;$('knob').style.transform=`translate(${x}px,${y}px)`;}stick.addEventListener('pointermove',e=>{if(e.pointerId===joy.id)updateJoy(e);});for(const evt of ['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(evt,e=>{if(e.pointerId===joy.id){joy.x=joy.y=0;joy.id=null;$('knob').style.transform='';}});
renderer.domElement.addEventListener('pointerdown',e=>{if(mode!=='walk'||lookId!==null)return;lookId=e.pointerId;lastX=e.clientX;lastY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(e.pointerId!==lookId)return;yaw-=(e.clientX-lastX)*.005;pitch=Math.max(-.48,Math.min(1.15,pitch+(e.clientY-lastY)*.004));lastX=e.clientX;lastY=e.clientY;$('lookhint').style.opacity='0';});for(const evt of ['pointerup','pointercancel','lostpointercapture'])renderer.domElement.addEventListener(evt,e=>{if(lookId===e.pointerId)lookId=null;});
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',clearInput);document.addEventListener('visibilitychange',()=>{clearInput();clock.getDelta();});
$('home').addEventListener('click',()=>{clearInput();player.position.set(28,0,12);yaw=.1;pitch=.2;camera.position.copy(player.position).add(new T.Vector3(0,4,9));});$('full').addEventListener('click',async()=>{try{if(!document.fullscreenElement){await document.documentElement.requestFullscreen?.();}else await document.exitFullscreen();}catch{}});
renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('error').hidden=false;});
function move(dt){let x=joy.x+(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('q')||keys.has('a')||keys.has('arrowleft')?1:0),z=joy.y+(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('z')||keys.has('w')||keys.has('arrowup')?1:0);let len=Math.hypot(x,z);moving=Math.min(1,len);if(len>.06){x/=Math.max(1,len);z/=Math.max(1,len);const dx=(x*Math.cos(yaw)+z*Math.sin(yaw))*dt*10,dz=(-x*Math.sin(yaw)+z*Math.cos(yaw))*dt*10;const p=player.position;let next=resolveMove(p.x+dx,p.z+dz,p.y,p.x,p.z);if(!next)next=resolveMove(p.x+dx,p.z,p.y,p.x,p.z);if(!next)next=resolveMove(p.x,p.z+dz,p.y,p.x,p.z);if(next)p.set(next.x,next.y,next.z);let a=Math.atan2(dx,dz),diff=Math.atan2(Math.sin(a-player.rotation.y),Math.cos(a-player.rotation.y));player.rotation.y+=diff*Math.min(1,dt*12);walk+=dt*11*moving;}legs.forEach((l,i)=>l.rotation.x=Math.sin(walk+i*Math.PI)*.45*moving);arms.forEach((a,i)=>a.rotation.x=-Math.sin(walk+i*Math.PI)*.4*moving);robe.position.y=.9+Math.abs(Math.sin(walk))*.035*moving;playerShadow.position.set(player.position.x,player.position.y+.025,player.position.z);
viewTarget.copy(player.position).add(new T.Vector3(0,1.9,0));const dist=player.position.y>2?8:8.5;desired.set(Math.sin(yaw)*Math.cos(pitch)*dist,2+Math.sin(pitch)*dist,Math.cos(yaw)*Math.cos(pitch)*dist).add(player.position);desired.y=Math.max(desired.y,ground(desired.x,desired.z)+1.1);camera.position.lerp(desired,1-Math.exp(-dt*10));camera.lookAt(viewTarget);solarMat.opacity=player.position.y>90?Math.max(.07,.92-(player.position.y-90)*.09):.92;halo.visible=player.position.y<89;}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.045),t=clock.elapsedTime;
if(mode==='intro'){camera.position.set(370+Math.sin(t*.07)*40,145,680);camera.lookAt(0,20,0);outside.rotation.y=Math.sin(t*.025)*.08;}
else if(mode==='approach'){let u=(t-startTime)/3.8;if(u<1){outside.rotation.y=0;const s=u*u*(3-2*u);camera.position.set(370*(1-s),145*(1-s)+15*s,680*(1-s)+294*s);camera.lookAt(0,15,276);$('fade').style.opacity=u>.85?String((u-.85)/.15):'0';}else{mode='tunnel';startTime=t;world.visible=true;outside.visible=false;scene.background=new T.Color('#a7b7a0');scene.fog=new T.Fog('#a7b7a0',115,490);$('fade').style.opacity='0';}}
else if(mode==='tunnel'){const u=Math.min(1,(t-startTime)/5.5),s=u*u*(3-2*u);camera.position.set(0,4,153-s*73);camera.lookAt(0,7,-35);if(u>=1)beginWalk();}else move(dt);
if(world.visible){bear.scale.y=1+Math.sin(t*1.3)*.018;ripples.forEach((r,i)=>{const s=1+((t*.35+r.userData.phase)%3);r.scale.set(s*1.8,s,1);r.material.opacity=.17*(1-(s-1)/3);});pollen.position.x=Math.sin(t*.13)*2;pollen.position.y=Math.sin(t*.3)*.6;waterMat.color.setHSL(.485+Math.sin(t*.3)*.008,.39,.5);}
renderer.render(scene,camera);}
animate();
